<?php
session_start();
require_once __DIR__.'/../lead-engine/config.php';
require_once __DIR__.'/../lead-engine/goliath-db.php';
if(empty($_SESSION['mp_dashboard_auth'])){header('Location:/dashboard/?next='.rawurlencode($_SERVER['REQUEST_URI']??'/dashboard/jessica-relationship-center.php'));exit;}
function h($v){return htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');}
function rows($s,$p=[]){try{return gdb_all($s,$p)?:[];}catch(Throwable $e){return [];}}
function one($s,$p=[]){try{return gdb_one($s,$p)?:[];}catch(Throwable $e){return [];}}
$key=defined('AFTER_HOURS_CRON_KEY')?AFTER_HOURS_CRON_KEY:'timetomakethedonuts';
$drafts=rows("SELECT ed.*, q.owner_name q_name,q.property_address q_address,q.town q_town,q.campaign,q.lead_type,q.priority,q.relationship_stage
 FROM jessica_email_drafts ed
 LEFT JOIN jessica_relationship_queue q ON q.id=ed.queue_id
 WHERE ed.status IN ('pending_approval','approved')
 ORDER BY CASE WHEN ed.status='pending_approval' THEN 0 ELSE 1 END, q.priority DESC, ed.created_at DESC
 LIMIT 100");
$phoneOnly=rows("SELECT * FROM jessica_relationship_queue WHERE status='drafted' AND id NOT IN (SELECT COALESCE(queue_id,0) FROM jessica_email_drafts) ORDER BY priority DESC, created_at DESC LIMIT 50");
$appts=rows("SELECT * FROM appointment_requests WHERE status IN ('draft','pending','confirmed') ORDER BY COALESCE(start_time,created_at) ASC LIMIT 20");
$stats=[
 'drafts'=>(int)(one("SELECT COUNT(*) c FROM jessica_email_drafts WHERE status='pending_approval'")['c']??0),
 'approved'=>(int)(one("SELECT COUNT(*) c FROM jessica_email_drafts WHERE status='approved'")['c']??0),
 'sent'=>(int)(one("SELECT COUNT(*) c FROM jessica_email_drafts WHERE status='sent'")['c']??0),
 'queue'=>(int)(one("SELECT COUNT(*) c FROM jessica_relationship_queue WHERE status IN ('queued','drafted','approved')")['c']??0)
];
