<section class="stats"><div class="stat"><b><?=h($stats['drafts'])?></b><span>Need Review</span></div><div class="stat"><b><?=h($stats['approved'])?></b><span>Approved</span></div><div class="stat"><b><?=h($stats['sent'])?></b><span>Sent</span></div><div class="stat"><b><?=h($stats['queue'])?></b><span>Queue</span></div></section>
