<?php foreach($drafts as $d): ?><article class="draft" id="draft-<?=h($d['id'])?>"><div class="draftHead" onclick="this.parentNode.classList.toggle('open')"><div><b><?=h($d['to_name']?:$d['q_name']?:'Contact')?></b><div class="muted"><?=h($d['to_email'])?> · <?=h($d['q_town'])?> · <?=h($d['campaign'])?></div><span class="pill"><?=h($d['status'])?></span><span class="pill"><?=h($d['recommended_blog'])?></span></div><button class="btn">Open</button></div><div class="body"><form onsubmit="jessicaAction(event,this)"><input type="hidden" name="key" value="<?=h($key)?>"><input type="hidden" name="draft_id" value="<?=h($d['id'])?>"><label>Subject</label><input name="subject" value="<?=h($d['subject'])?>"><label>HTML Body</label><textarea name="body_html"><?=h($d['body_html'])?></textarea><label>Text Body</label><textarea name="body_text" style="min-height:120px"><?=h($d['body_text'])?></textarea><div class="row"><button class="btn" name="action" value="save">Save</button><button class="btn blue" name="action" value="approve">Approve</button><button class="btn green" name="action" value="send">Send Now</button><span class="saveMsg">Saved</span></div></form></div></article><?php endforeach; ?>
</main><aside><section class="panel"><h2>Phone-Only Leads</h2><?php foreach($phoneOnly as $p): ?><div class="sideCard"><b><?=h($p['owner_name'])?></b><div class="muted"><?=h($p['property_address'])?> · <?=h($p['town'])?></div><span class="pill"><?=h($p['campaign'])?></span></div><?php endforeach; ?></section><section class="panel"><h2>Appointments</h2><?php foreach($appts as $a): ?><div class="sideCard"><b><?=h($a['title'])?></b><div class="muted"><?=h($a['client_name'])?> · <?=h($a['start_time'])?></div><div><?=h($a['location'])?></div></div><?php endforeach; ?></section></aside></section></div>
<script>
async function jessicaAction(e,form){e.preventDefault();const fd=new FormData(form);const clicked=e.submitter;if(clicked&&clicked.name)fd.set(clicked.name,clicked.value);const res=await fetch('/lead-engine/jessica-draft-action-v96-2.php',{method:'POST',body:fd});const data=await res.json();const msg=form.querySelector('.saveMsg');msg.style.display='inline';msg.textContent=data.ok?'Done.':'Error: '+(data.error||'failed');if(data.ok&&fd.get('action')==='send')setTimeout(()=>location.reload(),800);}
</script></body></html>